import {runInstalledAgent} from './installed-agent.mjs';
const input=String.raw`
function b(p,name,props={}){return Insert(p,{type:'frame',name,layout:'vertical',gap:16,alignItems:'start',width:'fill_container',height:'fit_content',...props})}function t(p,name,content,size=14,color='#223C32',props={}){return Insert(p,{type:'text',name,content,fontFamily:'Inter',fontSize:size,fill:color,textGrowth:'auto',...props})}
let screen=b(document,'Agent A — Profile workspace',{x:0,y:1100,width:760,height:620,padding:48,gap:32,fill:'#F7F8F2',clip:true});let header=b(screen,'Profile header',{layout:'horizontal',gap:16,alignItems:'center'});let avatar=b(header,'Avatar',{width:72,height:72,alignItems:'center',justifyContent:'center',gap:8,fill:'#DCE7D0',cornerRadius:36});t(avatar,'Avatar initials','JM',24,'#577549',{fontWeight:'600'});let identity=b(header,'Identity',{gap:8});t(identity,'Name','Jordan Morgan',28,'#223C32',{fontWeight:'600'});t(identity,'Role','Product designer · Building thoughtful experiences',13,'#83947B');let summary=b(screen,'About section',{padding:24,gap:16,fill:'#FFFFFF',cornerRadius:16});t(summary,'About title','A little about me',18,'#223C32',{fontWeight:'600'});t(summary,'About description','Turning complex ideas into calm, useful products.\nCurrently exploring design systems and collaborative spaces.',14,'#7B8B72',{lineHeight:1.6});let stats=b(screen,'Profile statistics',{layout:'horizontal',gap:16,alignItems:'center'});for(let [value,label]of[['24','Projects created'],['08','Collaborators'],['156','Ideas saved']]){let c=b(stats,label+' card',{padding:24,gap:8,fill:'#E9EFDF',cornerRadius:12});t(c,label+' value',value,28,'#4C6941',{fontWeight:'600'});t(c,label+' label',label,12,'#819174')};let footer=b(screen,'Profile actions',{layout:'horizontal',gap:16,alignItems:'center'});let button=b(footer,'Edit profile button',{width:'fit_content',padding:16,gap:8,fill:'#527048',cornerRadius:8});t(button,'Edit profile label','Edit profile',13,'#FFFFFF',{fontWeight:'600'});t(footer,'Profile visibility','Your profile is visible to your team.',12,'#8A997F');Print('AGENT_A_FRAME:'+screen);
`;
const receipt=await runInstalledAgent({hostFile:process.argv[2],agent:'agent-a',input});
console.log(JSON.stringify({agent:receipt.agent,sessionId:receipt.sessionId,openToModificationMs:receipt.openToModificationMs,result:receipt.result.content?.filter(c=>c.type==='text').map(c=>c.text).join('\n').slice(0,500)}));
